1) In `func (b *randomBalancer) Next(c echo.Context) *ProxyTarget`, add an empty-target-list guard so it returns nil instead of calling rand.Intn(0) (which panics with "invalid argument to Intn"). Final function must be exactly:

```go
// Next randomly returns an upstream target.
func (b *randomBalancer) Next(c echo.Context) *ProxyTarget {
	if b.random == nil {
		b.random = rand.New(rand.NewSource(int64(time.Now().Nanosecond())))
	}
	b.mutex.RLock()
	defer b.mutex.RUnlock()
	if len(b.targets) == 0 {
		return nil
	}
	return b.targets[b.random.Intn(len(b.targets))]
}
```

2) In `func (b *roundRobinBalancer) Next(c echo.Context) *ProxyTarget`, add the same empty-list guard before the modulo (which currently panics with "integer divide by zero"). Final function must be exactly:

```go
// Next returns an upstream target using round-robin technique.
func (b *roundRobinBalancer) Next(c echo.Context) *ProxyTarget {
	if len(b.targets) == 0 {
		return nil
	}
	b.i = b.i % uint32(len(b.targets))
	t := b.targets[b.i]
	atomic.AddUint32(&b.i, 1)
	return t
}
```

