package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Bug 2: unmatched request must report empty path
func TestZZVerifyUnmatchedPath(t *testing.T) {
	e := New()
	e.GET("/users/:id", func(c Context) error { return c.NoContent(http.StatusOK) })
	got := "unset"
	e.HTTPErrorHandler = func(err error, c Context) {
		got = c.Path()
		e.DefaultHTTPErrorHandler(err, c)
	}
	req := httptest.NewRequest(http.MethodGet, "/does-not-exist", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	if got != "" {
		t.Fatalf("unmatched: Path()=%q, want \"\"", got)
	}
	if rec.Code != http.StatusNotFound {
		t.Fatalf("unmatched status=%d, want 404", rec.Code)
	}

	// matched request must still report the registered route path
	matched := "unset"
	e2 := New()
	e2.GET("/users/:id", func(c Context) error { matched = c.Path(); return c.NoContent(http.StatusOK) })
	req2 := httptest.NewRequest(http.MethodGet, "/users/1", nil)
	e2.ServeHTTP(httptest.NewRecorder(), req2)
	if matched != "/users/:id" {
		t.Fatalf("matched: Path()=%q, want /users/:id", matched)
	}
}

// Bug 3: bogus scheme headers must be ignored, valid fallback used, default http
func TestZZVerifyScheme(t *testing.T) {
	e := New()
	c := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())
	c.Request().Header.Set("X-Forwarded-Proto", "ftp")
	c.Request().Header.Set("X-Url-Scheme", "https")
	if s := c.Scheme(); s != "https" {
		t.Fatalf("Scheme()=%q, want https", s)
	}
	c2 := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())
	c2.Request().Header.Set("X-Forwarded-Proto", "ftp")
	if s := c2.Scheme(); s != "http" {
		t.Fatalf("Scheme()=%q, want http", s)
	}
	c3 := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())
	c3.Request().Header.Set("X-Forwarded-Proto", "https")
	if s := c3.Scheme(); s != "https" {
		t.Fatalf("Scheme()=%q, want https", s)
	}
}
```

